(() => {
  const original = document.querySelector('#esc-about');
  if (!original || document.querySelector('.urvion-about-stage')) return;
  original.id = 'esc-about-original';
  const stage = document.createElement('section');
  stage.id = 'esc-about'; stage.className = 'urvion-about-stage';
  stage.innerHTML = `<div class="urvion-about-sticky"><div class="urvion-about-media" aria-hidden="true"></div><div class="urvion-about-track"><article class="urvion-about-panel about-opening"><div class="about-opening-layout"><p class="about-label">ECO-SOCIAL CLUB · SILICON UNIVERSITY, ODISHA</p><img class="about-opening-logo" src="assets/images/urvion-volume-2-logo.webp" alt="URVION Volume 2"><p class="about-cue">SCROLL TO DISCOVER ESC →</p></div></article><article class="urvion-about-panel"><div class="about-content"><p class="about-label"><b>CHAPTER 01</b> WHO WE ARE</p><h2>ABOUT <em>ECO-SOCIAL CLUB</em></h2><div class="about-copy"><p>The Eco-Social Club (ESC) of Silicon University, Odisha is a student-led initiative committed to advancing environmental sustainability, social responsibility and individual well-being. Guided by collective action and responsible engagement, we create awareness, outreach and impactful initiatives.</p></div></div></article><article class="urvion-about-panel"><div class="about-content"><p class="about-label"><b>CHAPTER 02</b> ECOLOGY · SOCIAL WELFARE · ZEAL</p><h2>IDEAS INTO <em>MEANINGFUL ACTION</em></h2><div class="about-copy"><p>Across three core domains, ESC gives students a platform to turn ideas into action through collaborative, community-oriented programmes. URVION brings sustainability-driven innovation to life for a growing community.</p></div></div></article><article class="urvion-about-panel"><div class="about-content"><p class="about-label"><b>CHAPTER 03</b> OUR COMMUNITY &amp; VISION</p><h2>A COMMUNITY <em>FOR CHANGE</em></h2><div class="about-copy"><p>ESC cultivates socially conscious, environmentally responsible and proactive individuals who work together towards a healthier, more inclusive and sustainable future.</p></div><div class="about-metrics"><span><strong>500+</strong><small>REGISTERED MEMBERS</small></span><span><strong>400+</strong><small>URVION PARTICIPANTS</small></span><span><strong>03</strong><small>CORE DOMAINS</small></span></div><a href="index.html#events">EXPLORE THE FOUR EXPEDITIONS →</a></div></article></div></div>`;
  original.before(stage);
  const track = stage.querySelector('.urvion-about-track'), panels = [...stage.querySelectorAll('.urvion-about-panel')];
  stage.setAttribute('aria-label','About the Eco-Social Club');stage.setAttribute('aria-roledescription','carousel');
  stage.querySelector('.about-cue').textContent='DISCOVER OUR STORY →';
  const controls=document.createElement('div');controls.className='about-swap-controls';
  controls.innerHTML='<button type="button" class="about-prev" aria-label="Previous About chapter">← Previous</button><span class="about-swap-status" aria-live="polite"></span><button type="button" class="about-next" aria-label="Next About chapter">Next →</button>';
  stage.querySelector('.urvion-about-sticky').append(controls);
  const prev=controls.querySelector('.about-prev'),next=controls.querySelector('.about-next'),status=controls.querySelector('.about-swap-status');let index=0;
  function show(value){index=Math.max(0,Math.min(panels.length-1,value));track.style.setProperty('transform',`translate3d(${-25*index}%,0,0)`,'important');panels.forEach((panel,i)=>{panel.classList.toggle('is-active',i===index);panel.inert=i!==index;panel.setAttribute('aria-hidden',String(i!==index));});prev.disabled=index===0;next.disabled=index===panels.length-1;status.textContent=`CHAPTER 0${index} / 03`;}
  prev.addEventListener('click',()=>show(index-1));next.addEventListener('click',()=>show(index+1));show(0);
  const sectionHashes=['#esc-about','#pillars-of-pyrite-section'];
  function land(){if(!sectionHashes.includes(location.hash))return;const target=document.querySelector(location.hash);if(target)scrollTo({top:scrollY+target.getBoundingClientRect().top,behavior:'instant'});}
  document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(!link)return;const url=new URL(link.href,location.href);if(!sectionHashes.includes(url.hash)||url.pathname!==location.pathname)return;event.preventDefault();history.pushState(null,'',url.hash);requestAnimationFrame(land);});
  addEventListener('hashchange',land);
  if(sectionHashes.includes(location.hash)){requestAnimationFrame(land);if(document.readyState!=='complete')addEventListener('load',land,{once:true});}
})();
